// Which build is this process actually serving?
//
// It exists for scripts/serve.sh. A restarted server that fails to bind leaves
// the previous one holding the port, and every readiness check that only asks
// "does / return 200?" is then answered by the stale server — which by that
// point is serving a build whose files the new `next build` has deleted, so the
// pages 500 and the test run blames the app.
//
// The build id is regenerated by every build, so comparing it against
// .next/BUILD_ID cannot be satisfied by yesterday's process.

import { readFileSync } from "node:fs";
import path from "node:path";
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";

let cached: string | null = null;

export async function GET() {
  if (cached == null) {
    try {
      cached = readFileSync(path.join(process.cwd(), ".next", "BUILD_ID"), "utf8").trim();
    } catch {
      // Development has no BUILD_ID file; say so rather than inventing one.
      cached = "dev";
    }
  }
  return NextResponse.json({ buildId: cached });
}
